function animate(env,el,p){
    var sy=["$","\u20AC","\u00A3","\u00A5","Rp"][p.symbol%5];
    var dc=Math.round(p.decimals);
    el.text=el.text.replace(/\d+(\.\d+)?/g, function(s){ var n=parseFloat(s).toFixed(dc); var pr=n.split("."); pr[0]=pr[0].replace(/\B(?=(\d{3})+(?!\d))/g, ","); return sy+pr.join("."); });
    return el;
}
